"""Continuous, bounded native GN no-contact guard for two Bundle centerlines.

The guard tests the authored polylines and their actual POLY/Bezier paths.
Exact mode uses complete segment distances, including endpoint contact and
collinear overlap. Cubics use a chord-distance enclosure: the curve differs
from its chord by at most the largest displacement of its two interior
Bernstein controls from the corresponding linear controls. Pairs are accepted
only when that enclosure proves positive clearance. Ambiguous pairs are split
by de Casteljau; exhausting the bounded work/depth reports uncertainty.

This is independent of the pavement footprint: overlapping pavement is legal.
The XY contact tolerance is 10 micrometres in the local metre coordinate frame.
Z is deliberately ignored: the caller supplies members of one same-level Bundle.
"""

CONTACT_TOLERANCE = 1.e-5
MAX_INITIAL_PAIRS = 65536
MAX_ACTIVE_PAIRS = 8192
MAX_REFINEMENTS = 48
CONTACT_CODE = 40
UNCERTAIN_CODE = 41


def _size(g, geometry, component='POINTCLOUD'):
    node = g.node('GeometryNodeAttributeDomainSize', 'Bundle guard bounded work size')
    node.component = component
    g.set(geometry, node.inputs['Geometry'])
    return node.outputs['Point Count']


def _select(g, geometry, selection, label):
    node = g.node('GeometryNodeSeparateGeometry', label)
    node.domain = 'POINT'
    g.set(geometry, node.inputs['Geometry'])
    g.set(selection, node.inputs['Selection'])
    return node.outputs['Selection']


def _mix(g, a, b, factor=.5):
    return g.vector('ADD', a, g.vector('SCALE', g.vector('SUBTRACT', b, a), factor))


def _planar(g, value):
    return g.xyz(g.component(value, 'X'), g.component(value, 'Y'))


def _clamp(g, value):
    return g.math('MINIMUM', 1., g.math('MAXIMUM', 0., value))


def _segment_distance(g, a, b, c, d):
    """Return complete XY segment distance and midpoint of a closest pair."""
    def projection(p, x, y):
        direction = g.vector('SUBTRACT', y, x)
        numerator = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', p, x), direction)
        denominator = g.vector('DOT_PRODUCT', direction, direction)
        t = _clamp(g, g.math('DIVIDE', numerator, g.math('MAXIMUM', denominator, 1.e-30)))
        q = _mix(g, x, y, t)
        return g.vector('DISTANCE', p, q), _mix(g, p, q)

    distance, location = projection(a, c, d)
    for p, x, y in ((b, c, d), (c, a, b), (d, a, b)):
        candidate, candidate_location = projection(p, x, y)
        closer = g.compare(candidate, distance, 'LESS_THAN')
        location = g.switch(closer, location, candidate_location, 'VECTOR')
        distance = g.math('MINIMUM', distance, candidate)
    ab, cd, ac = [g.vector('SUBTRACT', y, x) for x, y in ((a, b), (c, d), (a, c))]
    cross = lambda x, y: g.component(g.vector('CROSS_PRODUCT', x, y), 'Z')
    determinant = cross(ab, cd)
    not_parallel = g.compare(g.math('ABSOLUTE', determinant), 1.e-25, 'GREATER_THAN')
    safe = g.switch(not_parallel, 1., determinant)
    t, u = g.math('DIVIDE', cross(ac, cd), safe), g.math('DIVIDE', cross(ac, ab), safe)
    crossing = g.all(not_parallel, g.compare(t, 0., 'GREATER_EQUAL'),
                     g.compare(t, 1., 'LESS_EQUAL'), g.compare(u, 0., 'GREATER_EQUAL'),
                     g.compare(u, 1., 'LESS_EQUAL'))
    return (g.switch(crossing, distance, 0.),
            g.switch(crossing, location, _mix(g, a, b, t), 'VECTOR'))


def _segments(g, geometry, count, degree=0, *, source_start=0):
    """Produce one point with four Bernstein controls for each complete span."""
    index = g.node('GeometryNodeInputIndex', 'Bundle segment index').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Actual centerline controls').outputs[0]
    segment_count = g.math('MAXIMUM', 0., g.math('SUBTRACT', count, 1.))
    points = g.node('GeometryNodePoints', 'One guard record per original span')
    g.set(g.math('MINIMUM', 512, segment_count), points.inputs['Count'])
    start = g.math('ADD', source_start, index)
    end = g.math('ADD', start, 1.)
    p0 = _planar(g, g.sample(geometry, position, start, 'FLOAT_VECTOR'))
    p3 = _planar(g, g.sample(geometry, position, end, 'FLOAT_VECTOR'))
    smooth = g.compare(degree, 3, kind='INT')
    controls = [p0,
        g.switch(smooth, _mix(g, p0, p3, 1./3.),
                 _planar(g, g.sample(geometry, g.named('st_curve_handle_right', 'FLOAT_VECTOR'), start, 'FLOAT_VECTOR')), 'VECTOR'),
        g.switch(smooth, _mix(g, p0, p3, 2./3.),
                 _planar(g, g.sample(geometry, g.named('st_curve_handle_left', 'FLOAT_VECTOR'), end, 'FLOAT_VECTOR')), 'VECTOR'),
        p3]
    result = points.outputs['Points']
    for k, value in enumerate(controls):
        result = g.store(result, 'st_bc_p'+str(k), value, 'FLOAT_VECTOR')
    result = g.store(result, 'st_bc_linear', g.boolean('NOT', smooth), 'BOOLEAN')
    valid = g.all(g.compare(count, 2, 'GREATER_EQUAL'), g.compare(count, 512, 'LESS_EQUAL'),
                  g.either(g.compare(degree, 0, kind='INT'), g.compare(degree, 3, kind='INT')))
    return result, valid


def _deviation(g, controls, linear):
    deviations = [g.vector('DISTANCE', controls[k], _mix(g, controls[0], controls[3], k/3.))
                  for k in (1, 2)]
    return g.switch(linear, g.math('MAXIMUM', *deviations), 0.)


def _split(g, p, second):
    a, b, c = _mix(g, p[0], p[1]), _mix(g, p[1], p[2]), _mix(g, p[2], p[3])
    d, e = _mix(g, a, b), _mix(g, b, c)
    f = _mix(g, d, e)
    return [g.switch(second, x, y, 'VECTOR') for x, y in zip((p[0], a, d, f), (f, e, c, p[3]))]


def _pair_guard(g, first, second, input_valid=True):
    """Test segment/cubic records; return scalar validity, location and code."""
    index = g.node('GeometryNodeInputIndex', 'Bundle candidate pair index').outputs[0]
    na, nb = _size(g, first), _size(g, second)
    total = g.math('MULTIPLY', na, nb)
    budget = g.all(input_valid, g.compare(total, MAX_INITIAL_PAIRS, 'LESS_EQUAL'))
    points = g.node('GeometryNodePoints', 'Complete original centerline span pairs')
    g.set(g.math('MINIMUM', total, MAX_INITIAL_PAIRS), points.inputs['Count'])
    pairs = g.switch(budget, None, points.outputs['Points'], 'GEOMETRY')
    a_index = g.math('FLOOR', g.math('DIVIDE', index, g.math('MAXIMUM', nb, 1.)))
    b_index = g.math('MODULO', index, g.math('MAXIMUM', nb, 1.))
    for prefix, source, at in (('a', first, a_index), ('b', second, b_index)):
        for k in range(4):
            value = g.sample(source, g.named('st_bc_p'+str(k), 'FLOAT_VECTOR'), at, 'FLOAT_VECTOR')
            pairs = g.store(pairs, 'st_bc_'+prefix+str(k), value, 'FLOAT_VECTOR')
        pairs = g.store(pairs, 'st_bc_'+prefix+'_linear',
                        g.sample(source, g.named('st_bc_linear', 'BOOLEAN'), at, 'BOOLEAN'), 'BOOLEAN')
    initial_position = _mix(g,
        g.sample(first, g.named('st_bc_p0', 'FLOAT_VECTOR'), 0, 'FLOAT_VECTOR'),
        g.sample(second, g.named('st_bc_p0', 'FLOAT_VECTOR'), 0, 'FLOAT_VECTOR'))
    ri = g.node('GeometryNodeRepeatInput', 'Adaptive continuous Bundle contact certification')
    ro = g.node('GeometryNodeRepeatOutput', 'Proved clearance or explicit contact uncertainty')
    ro.repeat_items.clear()
    for kind, name in [('GEOMETRY', 'Pairs'), ('BOOLEAN', 'Contact'),
                       ('BOOLEAN', 'Uncertain'), ('VECTOR', 'Location')]:
        ro.repeat_items.new(kind, name)
    ri.pair_with_output(ro)
    both_linear = g.all(g.stat(first, g.named('st_bc_linear', 'BOOLEAN')),
                        g.stat(second, g.named('st_bc_linear', 'BOOLEAN')))
    g.set(g.switch(both_linear, MAX_REFINEMENTS, 1, 'INT'), ri.inputs['Iterations'])
    g.set(pairs, ri.inputs['Pairs'])
    ri.inputs['Contact'].default_value = False
    g.set(g.boolean('NOT', budget), ri.inputs['Uncertain'])
    g.set(initial_position, ri.inputs['Location'])
    active = ri.outputs['Pairs']
    a = [g.named('st_bc_a'+str(k), 'FLOAT_VECTOR') for k in range(4)]
    b = [g.named('st_bc_b'+str(k), 'FLOAT_VECTOR') for k in range(4)]
    # The Bezier convex hull lies inside its control box. This cheap broad
    # phase removes far-away pairs before the continuous distance enclosure.
    boxes = []
    for axis in ('X', 'Y'):
        lows, highs = [], []
        for controls in (a, b):
            values = [g.component(value, axis) for value in controls]
            lo, hi = values[0], values[0]
            for value in values[1:]:
                lo, hi = g.math('MINIMUM', lo, value), g.math('MAXIMUM', hi, value)
            lows.append(lo); highs.append(hi)
        boxes.append(g.compare(g.math('MAXIMUM', *lows),
                     g.math('ADD', g.math('MINIMUM', *highs), CONTACT_TOLERANCE), 'LESS_EQUAL'))
    active = _select(g, active, g.all(*boxes), 'Discard only disjoint continuous control boxes')
    da = _deviation(g, a, g.named('st_bc_a_linear', 'BOOLEAN'))
    db = _deviation(g, b, g.named('st_bc_b_linear', 'BOOLEAN'))
    error = g.math('ADD', da, db)
    distance, location = _segment_distance(g, a[0], a[3], b[0], b[3])
    contact = g.compare(g.math('ADD', distance, error), CONTACT_TOLERANCE, 'LESS_EQUAL')
    clear = g.compare(g.math('SUBTRACT', distance, error), CONTACT_TOLERANCE, 'GREATER_THAN')
    active = g.store(active, 'st_bc_location', location, 'FLOAT_VECTOR')
    hits = _select(g, active, contact, 'Certified centerline crossing touching or coincidence')
    found = g.compare(_size(g, hits), 0, 'GREATER_THAN')
    hit_position = g.sample(hits, g.named('st_bc_location', 'FLOAT_VECTOR'), 0, 'FLOAT_VECTOR')
    unresolved = _select(g, active, g.boolean('NOT', g.either(clear, contact)),
                         'Only mathematically unresolved curve pairs require refinement')
    nleft = _size(g, unresolved)
    over_budget = g.compare(nleft, MAX_ACTIVE_PAIRS//2, 'GREATER_THAN')
    uncertain_position = g.sample(unresolved, g.named('st_bc_location', 'FLOAT_VECTOR'), 0, 'FLOAT_VECTOR')
    stop = g.either(g.either(ri.outputs['Contact'], found), over_budget)
    unresolved = g.switch(stop, unresolved, None, 'GEOMETRY')
    duplicate = g.node('GeometryNodeDuplicateElements', 'Bisect the less certain continuous interval')
    duplicate.domain = 'POINT'
    duplicate.inputs['Amount'].default_value = 2
    g.set(unresolved, duplicate.inputs['Geometry'])
    second_half = g.compare(duplicate.outputs['Duplicate Index'], 1, kind='INT')
    split_a = g.compare(da, db, 'GREATER_EQUAL')
    aa, bb = _split(g, a, second_half), _split(g, b, second_half)
    refined = duplicate.outputs['Geometry']
    # Store all new controls before replacing any old control attribute.
    # Otherwise a later field could read an already changed earlier control.
    for prefix, old, new, choose in [('a', a, aa, split_a), ('b', b, bb, g.boolean('NOT', split_a))]:
        for k in range(4):
            refined = g.store(refined, 'st_bc_q'+prefix+str(k),
                              g.switch(choose, old[k], new[k], 'VECTOR'), 'FLOAT_VECTOR')
    for prefix in ('a', 'b'):
        for k in range(4):
            refined = g.store(refined, 'st_bc_'+prefix+str(k),
                              g.named('st_bc_q'+prefix+str(k), 'FLOAT_VECTOR'), 'FLOAT_VECTOR')
    g.set(refined, ro.inputs['Pairs'])
    g.set(g.either(ri.outputs['Contact'], found), ro.inputs['Contact'])
    g.set(g.either(ri.outputs['Uncertain'], over_budget), ro.inputs['Uncertain'])
    updated = g.switch(over_budget, ri.outputs['Location'], uncertain_position, 'VECTOR')
    updated = g.switch(found, updated, hit_position, 'VECTOR')
    updated = g.switch(ri.outputs['Contact'], updated, ri.outputs['Location'], 'VECTOR')
    g.set(updated, ro.inputs['Location'])
    left = g.compare(_size(g, ro.outputs['Pairs']), 0, 'GREATER_THAN')
    unresolved_position = g.sample(ro.outputs['Pairs'], g.named('st_bc_location', 'FLOAT_VECTOR'), 0, 'FLOAT_VECTOR')
    final_position = g.switch(left, ro.outputs['Location'], unresolved_position, 'VECTOR')
    uncertain = g.either(ro.outputs['Uncertain'], left)
    code = g.switch(ro.outputs['Contact'], g.switch(uncertain, 0, UNCERTAIN_CODE, 'INT'), CONTACT_CODE, 'INT')
    return {'valid': g.compare(code, 0, kind='INT'), 'position': final_position, 'code': code}


def check(g, curves, owner, partner, *, sources=None, paths=None):
    """Check two member CURVE indices and optionally their complete raw paths.

    Returns ``{'valid': bool, 'position': vector, 'code': int}`` scalar sockets.
    Codes: 0 proved separate; 40 centerline contact within tolerance; 41 bounded
    certification could not decide. The caller attaches the two Section/Street
    IDs and Bundle ID to its local diagnostic. A rejected pair must not erase
    independent Bundles. Raw source checking is recommended because junction
    trimming must not hide contacts between the original input polylines.
    """
    index = g.node('GeometryNodeInputIndex', 'Bundle member spline index').outputs[0]
    records, validities = [], []
    for at in (owner, partner):
        selected = g.node('GeometryNodeSeparateGeometry', 'One actual Bundle member spline')
        selected.domain = 'CURVE'
        g.set(curves, selected.inputs['Geometry'])
        g.set(g.compare(index, at, kind='INT'), selected.inputs['Selection'])
        geometry = selected.outputs['Selection']
        count = _size(g, geometry, 'CURVE')
        degree = g.sample(curves, g.named('st_sweep_interpolation', 'INT'), at, 'INT', 'CURVE')
        record, valid = _segments(g, geometry, count, degree)
        records.append(record); validities.append(valid)
    current = _pair_guard(g, *records, g.all(*validities))
    if sources is None or paths is None:
        return current
    raw, raw_valid = [], []
    for at in (owner, partner):
        # Sweep indices may group several Sections. Check every original raw
        # span, including trimmed portions; do not connect unrelated records.
        chain_index = g.named('st_path_chain_index')
        belongs = g.switch(chain_index.node.outputs['Exists'], index, chain_index, 'INT')
        selected = _select(g, paths, g.compare(belongs, at, kind='INT'), 'Every source Section of this complete member')
        count = _size(g, selected, 'MESH')
        ri = g.node('GeometryNodeRepeatInput', 'Raw spans of all member Sections')
        ro = g.node('GeometryNodeRepeatOutput', 'Original authored Bundle segments')
        ro.repeat_items.clear(); ro.repeat_items.new('GEOMETRY', 'Segments'); ro.repeat_items.new('BOOLEAN', 'Valid')
        ri.pair_with_output(ro); ri.inputs['Valid'].default_value=True; g.set(count,ri.inputs['Iterations'])
        start = g.sample(selected, g.named('st_path_start'), ri.outputs['Iteration'])
        n = g.sample(selected, g.named('st_path_count'), ri.outputs['Iteration'])
        record, valid = _segments(g, sources, n, source_start=start)
        join = g.node('GeometryNodeJoinGeometry', 'Keep separate authored spans for contact testing')
        g.set(ri.outputs['Segments'],join.inputs['Geometry']);g.set(record,join.inputs['Geometry'])
        g.set(join.outputs['Geometry'],ro.inputs['Segments']);g.set(g.all(ri.outputs['Valid'],valid),ro.inputs['Valid'])
        raw.append(ro.outputs['Segments']);raw_valid.append(g.all(ro.outputs['Valid'],g.compare(count,0,'GREATER_THAN','INT')))
    authored = _pair_guard(g, *raw, g.all(*raw_valid))
    use_current = g.compare(authored['code'], 0, kind='INT')
    return {'valid': g.all(authored['valid'], current['valid']),
            'position': g.switch(use_current, authored['position'], current['position'], 'VECTOR'),
            'code': g.switch(use_current, authored['code'], current['code'], 'INT')}
